def solve_n_queens(n, fixed_positions):
    board = [-1] * n
    for row, col in fixed_positions.items():
        board[row] = col

    def is_safe(row, col):
        for i in range(n):
            if board[i] != -1:
                if board[i] == col:
                    return False
                if abs(board[i] - col) == abs(i - row):
                    return False
        return True

    def backtrack(row):
        if row == n:
            return True

        if board[row] != -1:
            return backtrack(row + 1)

        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    else:
        return None

fixed = {4: 4, 6: 1}
solution = solve_n_queens(14, fixed)
print(solution)

def is_valid_solution(n, solution):
    if len(solution) != n:
        return False

    # Check rows (implicitly satisfied by the structure)
    # Check columns
    if len(set(solution)) != n:
        return False

    # Check diagonals
    for i in range(n):
        for j in range(i + 1, n):
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False
    return True

solution = [2, 0, 7, 10, 4, 9, 1, 13, 11, 6, 8, 12, 5, 3]
fixed = {4: 4, 6: 1}

valid = is_valid_solution(14, solution)
fixed_satisfied = all(solution[row] == col for row, col in fixed.items())

print(f"Valid: {valid}")
print(f"Fixed satisfied: {fixed_satisfied}")
